export type Query = {
  readonly __typename?: "Query"
  /** Agent-session projection for one run when `gen_ai` producer spans exist. */
  readonly agentSession: Maybe<AgentSessionOut>
  /**
   * Recent evaluation audit rows for one rule, newest first (bounded
   * retention: last 500 per rule).
   */
  readonly alertChecks: ReadonlyArray<AlertCheck>
  /** Notification destinations, most recently updated first. */
  readonly alertDestinations: ReadonlyArray<AlertDestination>
  readonly alertIncident: Maybe<AlertIncident>
  /** Incidents newest-first; `status` filters open|resolved. */
  readonly alertIncidents: ReadonlyArray<AlertIncident>
  readonly alertRule: Maybe<AlertRule>
  /** Per-group rolling evaluation state for one rule. */
  readonly alertRuleStates: ReadonlyArray<AlertRuleState>
  /** Alert rules, most recently updated first (plan 167). */
  readonly alertRules: ReadonlyArray<AlertRule>
  /** Span-attribute overrepresentation in selected vs baseline windows. */
  readonly attributeCompare: ReadonlyArray<AttributeCompareRow>
  /** Periodic daemon work grouped by cycle name (`background.cycle` spans). */
  readonly backgroundCycles: ReadonlyArray<BackgroundCycle>
  /**
   * The bounded, redacted, hypothesis-ranked evidence bundle — the agent
   * handoff artifact assembling trace + logs + metric windows together.
   * Exactly one anchor: `fingerprint` (issue), `invocationId`, or `traceId`
   * (spec §8). Null when the anchor does not exist.
   */
  readonly bundle: Maybe<BundleOut>
  /** Agent conversations (`gen_ai.conversation.id` spans) in one invocation. */
  readonly conversations: ReadonlyArray<Conversation>
  /** One saved dashboard by id. */
  readonly dashboard: Maybe<Dashboard>
  /** Saved user dashboards, most recently updated first. */
  readonly dashboards: ReadonlyArray<Dashboard>
  /** Missing-evidence detector for exactly one trace or run anchor. */
  readonly evidenceGaps: ReadonlyArray<EvidenceGap>
  /** Scalar span/resource attribute keys in a bounded time window. */
  readonly fieldKeys: ReadonlyArray<FieldKey>
  /** Bounded coverage/cardinality/top-values stats for one field key. */
  readonly fieldStats: FieldStats
  readonly health: Scalars["String"]["output"]
  /** Approximate quantile series from a histogram metric (q in 0..=1). */
  readonly histogramQuantile: ReadonlyArray<Point>
  /** One saved investigation by id. */
  readonly investigation: Maybe<Investigation>
  /** Saved investigations/cases, most recently updated first. */
  readonly investigations: ReadonlyArray<Investigation>
  /** One CLI invocation by id (wrapper-registered or auto-registered external). */
  readonly invocation: Maybe<Invocation>
  /**
   * Bounded invocation facet dimensions (service, app.mode,
   * cli.command.name, outcome) with per-value DISTINCT-invocation counts
   * for the invocations facet sidebar (plan 164). Bounds default to the
   * retained recent window.
   */
  readonly invocationFacets: ReadonlyArray<Facet>
  readonly invocations: ReadonlyArray<Invocation>
  readonly issue: Maybe<Issue>
  /**
   * Occurrence counts per bucket for one issue's sparkline, oldest
   * first. Defaults: the last 24 hours in one-hour buckets.
   */
  readonly issueTrend: ReadonlyArray<TrendPoint>
  /**
   * Grouped errors: filtered, sorted, paged (spec §8 `issues`). The
   * `query` argument substring-matches title, error type, and fingerprint;
   * `fromNanos`/`toNanos` window on last-seen; `tagKey`+`tagValue` filter
   * on the cached tags.
   */
  readonly issues: IssueList
  /** Detached jobs (producer/consumer span pairs sharing `job.id`). */
  readonly jobs: ReadonlyArray<Job>
  /** Summaries for traces referenced by this trace's span links. */
  readonly linkedTraces: ReadonlyArray<TraceSummary>
  /**
   * Log counts per time bucket under the same filters as `logs` — the
   * Discover-style histogram above the log table.
   */
  readonly logCountSeries: ReadonlyArray<Point>
  /**
   * Bounded log facet dimensions with per-value counts under the same
   * filters as `logs` (plan 164 facet sidebar).
   */
  readonly logFacets: ReadonlyArray<Facet>
  /** Drain-style log body patterns over a bounded sample (plan 165). */
  readonly logPatterns: ReadonlyArray<LogPattern>
  /**
   * Unified log browse (spec §8 `logs`): every filter optional, newest
   * first. `query` substring-matches the body; trace/run scoping
   * composes with the other filters.
   */
  readonly logs: ReadonlyArray<LogRecord>
  /** Logs surrounding one anchor timestamp, ascending. */
  readonly logsAround: ReadonlyArray<LogRecord>
  /** Logs produced by one run. */
  readonly logsByInvocation: ReadonlyArray<LogRecord>
  /** Logs correlated to one trace, time ascending. */
  readonly logsByTrace: ReadonlyArray<LogRecord>
  /**
   * Window-scoped metric explorer catalog (plan 168): canonical names with
   * kind (gauge|sum|histogram), unit, emitting services, last datapoint,
   * and finite-sample counts per the metric-summary contract. `q` is a
   * case-insensitive substring filter; `kind` filters one metric kind.
   */
  readonly metricCatalog: ReadonlyArray<MetricCatalogRow>
  /** Trace-linked exemplars for one metric, newest first. */
  readonly metricExemplars: ReadonlyArray<MetricExemplar>
  /** Distinct values for one metric label inside a time window. */
  readonly metricLabelValues: ReadonlyArray<Scalars["String"]["output"]>
  /** Groupable label/tag keys for one metric. */
  readonly metricLabels: ReadonlyArray<Scalars["String"]["output"]>
  /**
   * Distinct metric names seen by the store (drives the dashboard
   * builder), optionally prefix-filtered.
   */
  readonly metricNames: ReadonlyArray<Scalars["String"]["output"]>
  /**
   * The single shared metric read path (plan 168): typed kind + aggregation
   * legality (gauge→avg|min|max|last, sum→sum|rate|increase, histogram→p50|p95|p99|avg),
   * optional service filter and group-by, contract step rounding (≤120
   * buckets, minimum 1s). Explorer, dashboards, and alerts all consume this.
   */
  readonly metricQuery: MetricQueryOut
  /**
   * Aggregated series for a point metric (gauge/sum); agg one of
   * avg|min|max|sum|rate. With `groupBy` (an attribute key) one series
   * per value; without it a single series with a null `groupValue`
   * (spec §8 `metricSeries`). `invocationId` scopes to points whose resource
   * carried `cli.invocation.id` (run-anchored cross-analytics).
   */
  readonly metricSeries: ReadonlyArray<Series>
  /**
   * Invocation ids observed in telemetry (any tool exporting `cli.invocation.id`
   * — e.g. jackin'), newest activity first. Independent of wrapper
   * registration: this is how external runs appear in the UI.
   */
  readonly observedInvocations: ReadonlyArray<ObservedInvocation>
  readonly otlpGrpcPort: Scalars["Int"]["output"]
  readonly otlpHttpPort: Scalars["Int"]["output"]
  /**
   * Whole-system counters for an inclusive time window. Counts are strings
   * so large telemetry volumes never saturate GraphQL Int.
   */
  readonly overview: Overview
  /** Recent traces (root span + aggregates), newest first. */
  readonly recentTraces: ReadonlyArray<TraceSummary>
  /** Per-version service release windows in the selected time range. */
  readonly releases: ReadonlyArray<ReleaseWindow>
  /** Runtime metric lanes, scoped to exactly one service or run. */
  readonly runtimeSnapshot: ReadonlyArray<RuntimeMetric>
  /** Named saved page states, most recently updated first. */
  readonly savedViews: ReadonlyArray<SavedView>
  /** Screen visits (entered/exited event pairs) for an invocation or session. */
  readonly screenVisits: ReadonlyArray<ScreenVisit>
  /** Resource-identity catalog rows for services in the selected window. */
  readonly serviceCatalog: ReadonlyArray<ServiceCatalogRow>
  /** Service summary rows for the services index. */
  readonly serviceList: ReadonlyArray<ServiceSummary>
  /** Trace-path service graph over a bounded set of traces in the window. */
  readonly serviceMap: ServiceMap
  /**
   * The predefined service overview (spec §8): CPU, memory, request rate,
   * latency percentiles, error rate from well-known metric names, with
   * graceful absence.
   */
  readonly serviceOverview: ServiceOverview
  /** Trace-derived RED analytics; works even when a service emits no metrics. */
  readonly serviceRed: SpanRed
  /** Distinct service names (drives the service-overview selector). */
  readonly services: ReadonlyArray<Scalars["String"]["output"]>
  /**
   * Interactive sessions observed inside one invocation, oldest first
   * (from `session.start`/`session.end` log events).
   */
  readonly sessions: ReadonlyArray<Session>
  /** Per-signal count series for overview trend charts. */
  readonly signalCountSeries: ReadonlyArray<Point>
  /**
   * Raw read-only SQL against the telemetry engine (`GreptimeDB`) — the
   * engine's full query power over logs, traces, and metrics tables.
   * SELECT-shaped single statements only.
   */
  readonly sql: SqlResultOut
  /** Deterministic story timeline for exactly one trace or run anchor. */
  readonly story: ReadonlyArray<StoryBeat>
  /** Every span of one trace, start-time ascending (cross-service). */
  readonly trace: Maybe<Trace>
  /** Structural diff between two traces' span trees. */
  readonly traceCompare: TraceDiff
  /** Critical-path hops that gate one trace's latency. */
  readonly traceCriticalPath: CriticalPath
  /**
   * Duration p50/p95 of the current trace filter set (plan 164 preset
   * chips); duration bounds are not accepted so presets never feed back
   * into themselves.
   */
  readonly traceDurationStats: DurationStats
  /**
   * Parsed span events across one trace, time ascending. `namePrefix`
   * filters by event name (for example "rpc.message" or "exception").
   */
  readonly traceEvents: TraceEventsOut
  /**
   * Bounded facet dimensions with per-value distinct-trace counts for
   * the facet sidebar (plan 164).
   */
  readonly traceFacets: ReadonlyArray<Facet>
  /**
   * Filtered trace browse (UI Traces page / `parallax traces`): every
   * filter optional; filters hit the root span except `errorOnly`,
   * which looks at the whole trace.
   */
  readonly traces: ReadonlyArray<TraceSummary>
  /**
   * Traces produced by one run, summarized (root span + aggregates),
   * newest first. Open one via `trace(traceId:)`.
   */
  readonly tracesByInvocation: ReadonlyArray<TraceSummary>
  /**
   * Filtered, sorted, paged trace browse with total count for redesigned
   * trace list clients.
   */
  readonly tracesPage: TraceList
  /** Bounded user-action root spans (`ui.action`) for one invocation. */
  readonly uiActions: ReadonlyArray<UiAction>
  readonly version: Scalars["String"]["output"]
}

